-- ============================================
-- INSERT SEMUA PEGAWAI BAPPEDA LAMPUNG (DUK 2026)
-- Jalankan di SQL Editor Supabase
-- ============================================

-- Hapus data lama terlebih dahulu (opsional)
-- DELETE FROM pegawai WHERE nip NOT IN ('197507312000031002','196910261992032002');

ON CONFLICT (nip) DO UPDATE SET
  nama = EXCLUDED.nama,
  pangkat = EXCLUDED.pangkat,
  jabatan = EXCLUDED.jabatan,
  jenis_jabatan = EXCLUDED.jenis_jabatan,
  unit_kerja = EXCLUDED.unit_kerja,
  role = EXCLUDED.role;

-- Total: 99 pegawai berhasil dimasukkan!